def solution(to_currency, values):
    exchange_rate = 1.1363636
    result = []

    for value in values:
        if to_currency == 'USD':
            converted = value * exchange_rate
            formatted = f"${converted:,.2f}"
        elif to_currency == 'EUR':
            converted = value / exchange_rate
            formatted = f"{converted:,.2f}€"

        result.append(formatted)

    return result
